# Generate the 30x30 grid from the described repeated-tile pattern, then add matching-color bridges.
G=[[0]*30 for _ in range(30)]
starts=[1,8,15,22]
centers=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for tr,r in enumerate(starts):
    for tc,c in enumerate(starts):
        # frames are color 4; tile interior is 3x3
        for i in range(5):
            for j in range(5): G[r+i][c+j]=4
        for i in range(1,4):
            for j in range(1,4): G[r+i][c+j]=centers[tr][tc]
# Missing partial cells at row/col 29 are 4 as in input
for r in starts:
    G[r+0][29]=4; G[r+1][29]=4; G[r+2][29]=4; G[r+3][29]=4; G[r+4][29]=4
for c in starts:
    G[29][c:c+5]=[4]*5
# connect 3: same-color objects aligned across row groups 0 and 2, columns 0 and 3
for rr in [2,3,4,16,17,18]:
    for cc in [6,7,13,14,20,21]: G[rr][cc]=3
for cc in [2,3,4,23,24,25]:
    for rr in [6,7,13,14]: G[rr][cc]=3
# connect 8: matching objects across cols 1-2 in row groups 1 and 3
for rr in [9,10,11,23,24,25]:
    for cc in [13,14]: G[rr][cc]=8
# and across row groups 1-3 in tile columns 1-2
for cc in [9,10,11,16,17,18]:
    for rr in [13,14,20,21]: G[rr][cc]=8
print('\n'.join(' '.join(map(str,row)) for row in G))
